mapper.select:
SELECT stock_code AS stockCode, interval_type AS intervalType, trade_datetime AS tradeDateTime,
       open_price AS open, high_price AS high, low_price AS low, close_price AS close, volume
FROM price_history
WHERE stock_code = #{stockCode}
  AND interval_type = #{intervalType}
  AND deleted_at IS NULL
ORDER BY trade_datetime DESC
LIMIT #{limit}
